import sys, socket, ipaddress, os
sys.dont_write_bytecode=True
_ports=set()
_repo_store=os.getcwd()+'/.friday/'
_oldbind=socket.socket.bind
def _bind(self,address):
    result=_oldbind(self,address)
    if self.family in (socket.AF_INET,socket.AF_INET6): _ports.add(self.getsockname()[1])
    return result
socket.socket.bind=_bind
def _audit(event,args):
    if event in ('socket.connect','socket.sendto'):
        addr=args[1] if event=='socket.connect' else args[-1]
        if isinstance(addr,tuple):
            host,port=addr[:2]
            if host not in ('localhost','127.0.0.1','::1') or port not in _ports:
                raise RuntimeError('Independent review prohibited application network destination')
        else: raise RuntimeError('Independent review prohibited non-IP network')
    if event=='open':
        try: path=os.fspath(args[0])
        except TypeError:return
        if isinstance(path,str) and (path.startswith(os.path.expanduser('~/.friday/')) or path.startswith(_repo_store)):
            raise RuntimeError('Independent review prohibited user store')
sys.addaudithook(_audit)

